        static void ResourceModStrings()
        {
            Editor("mod.discard", "还有未应用的玩法 Mod 或键位更改。放弃这些更改吗？", "There are unapplied gameplay mod or binding changes. Discard them?", "ゲームプレイModまたはキー設定に未適用の変更があります。破棄しますか？", "적용하지 않은 게임플레이 모드 또는 키 설정 변경이 있습니다. 버릴까요?", "Есть неприменённые изменения игрового мода или клавиш. Отменить их?", "還有未套用的玩法 Mod 或按鍵變更。放棄這些變更嗎？", "Des modifications du mod de jeu ou des touches ne sont pas appliquées. Les abandonner ?", "Es gibt nicht angewendete Gameplay-Mod- oder Tastenänderungen. Verwerfen?", "Hay cambios del mod de juego o de teclas sin aplicar. ¿Descartarlos?", "Há alterações de mod de jogabilidade ou teclas não aplicadas. Descartá-las?", "Ci sono modifiche alla mod di gioco o ai tasti non applicate. Scartarle?", "มีการเปลี่ยนม็อดการเล่นหรือปุ่มที่ยังไม่ได้ใช้ ต้องการละทิ้งหรือไม่?", "Có thay đổi mod lối chơi hoặc phím chưa áp dụng. Bỏ các thay đổi này?", "Há alterações de mod de jogabilidade ou teclas por aplicar. Descartá-las?", "Hay cambios del mod de juego o de teclas sin aplicar. ¿Descartarlos?");
            Editor("mod.badge", "玩法 MOD", "GAMEPLAY MOD", "ゲームプレイMOD", "게임플레이 MOD", "ИГРОВОЙ МОД", "玩法 MOD", "MOD DE JEU", "GAMEPLAY-MOD", "MOD DE JUEGO", "MOD DE JOGABILIDADE", "MOD DI GIOCO", "ม็อดการเล่น", "MOD LỐI CHƠI", "MOD DE JOGABILIDADE", "MOD DE JUEGO");
            Editor("mod.checkbox", "完美防御无连点惩罚", "Perfect guard: no rapid-click penalty", "ジャストガードの連打ペナルティなし", "완벽 방어 연타 페널티 제거", "Идеальный блок без штрафа частых нажатий", "完美防禦無連點懲罰", "Garde parfaite sans pénalité de répétition", "Perfekte Abwehr ohne Strafe für schnelle Klicks", "Bloqueo perfecto sin penalización por clics rápidos", "Defesa perfeita sem penalidade por cliques rápidos", "Difesa perfetta senza penalità per clic rapidi", "ป้องกันสมบูรณ์โดยไม่มีโทษกดรัว", "Đỡ hoàn hảo không phạt nhấp liên tục", "Defesa perfeita sem penalização por cliques rápidos", "Bloqueo perfecto sin penalización por clics rápidos");
            Editor("mod.help", "查看说明", "View explanation", "説明を見る", "설명 보기", "Открыть описание", "查看說明", "Voir les explications", "Erklärung ansehen", "Ver explicación", "Ver explicação", "Vedi spiegazione", "ดูคำอธิบาย", "Xem giải thích", "Ver explicação", "Ver explicación");
            Editor("mod.protectionhelp", "勾选后取消连点防御惩罚，每次点击仍按游戏当前基础时机判定；难度、饰品和破防状态仍遵循游戏原规则。", "Enabling this removes the rapid-guard penalty. Each click still uses the game’s current base timing; difficulty, accessories and guard-break state follow the original rules.", "有効にすると防御連打のペナルティを解除します。各入力の判定時間はゲーム本来の値を使い、難易度・装飾品・体勢崩し状態も元のルールに従います。", "켜면 방어 연타 페널티를 없앱니다. 각 클릭의 판정 시간과 난이도, 장신구, 방어 붕괴 상태는 게임의 기존 규칙을 따릅니다.", "Включение убирает штраф частого блока. Каждое нажатие использует текущее базовое окно игры; сложность, аксессуары и состояние пробитой защиты работают по исходным правилам.", "勾選後取消連點防禦懲罰，每次點擊仍依遊戲目前基礎時機判定；難度、飾品和破防狀態仍遵循遊戲原規則。", "L’activation supprime la pénalité des gardes répétées. Chaque clic utilise le timing de base actuel du jeu ; difficulté, accessoires et état de garde brisée suivent les règles d’origine.", "Die Option entfernt die Strafe für schnelle Abwehrfolgen. Jeder Klick nutzt weiter das aktuelle Grundzeitfenster des Spiels; Schwierigkeit, Zubehör und gebrochene Abwehr folgen den ursprünglichen Regeln.", "Activarlo elimina la penalización por bloquear repetidamente. Cada clic conserva el intervalo base actual del juego; dificultad, accesorios y guardia rota siguen las reglas originales.", "A ativação remove a penalidade por defesas repetidas. Cada clique mantém o tempo base atual do jogo; dificuldade, acessórios e quebra de defesa seguem as regras originais.", "L’attivazione rimuove la penalità per difese ripetute. Ogni clic usa i tempi base attuali del gioco; difficoltà, accessori e guardia spezzata seguono le regole originali.", "เมื่อเปิดจะยกเลิกโทษป้องกันรัว แต่ละคลิกยังใช้จังหวะพื้นฐานปัจจุบันของเกม ระดับความยาก เครื่องประดับ และสถานะเสียการป้องกันยังเป็นไปตามกฎเดิม", "Bật tùy chọn để bỏ phạt đỡ liên tục. Mỗi lần nhấp vẫn dùng thời điểm cơ bản hiện tại của trò chơi; độ khó, phụ kiện và trạng thái vỡ thế đỡ vẫn theo quy tắc gốc.", "A ativação remove a penalização por defesas repetidas. Cada clique mantém o tempo base atual do jogo; dificuldade, acessórios e quebra de defesa seguem as regras originais.", "Activarlo elimina la penalización por bloquear repetidamente. Cada clic conserva el intervalo base actual del juego; dificultad, accesorios y guardia rota siguen las reglas originales.");
            Editor("mod.warning", "原版连点防御会缩短或停止刷新完美防御窗口；\n左键攻防同键时，连点攻击也会触发该惩罚。", "Rapid guards shorten or stop renewing the perfect-guard window.\nShared left-click attacks trigger the same penalty.", "元の防御連打ペナルティでジャストガードの受付時間が短縮・更新停止します。\n左クリックで攻防すると攻撃連打でも発生します。", "기본 방어 연타 페널티는 완벽 방어 판정 시간을 줄이거나 갱신을 멈춥니다.\n좌클릭 공격·방어 공유 시 공격 연타도 페널티를 일으킵니다.", "Частый блок сокращает окно идеального блока или прекращает его обновление.\nПри общей ЛКМ частые атаки тоже вызывают этот штраф.", "原版連點防禦會縮短或停止刷新完美防禦窗口；\n左鍵攻防同鍵時，連點攻擊也會觸發該懲罰。", "Les gardes répétées réduisent ou cessent de renouveler la fenêtre de garde parfaite.\nLes attaques répétées déclenchent aussi cette pénalité si le clic gauche fait les deux.", "Schnelle Abwehrfolgen verkürzen das Zeitfenster für perfekte Abwehr oder stoppen seine Erneuerung.\nBei gemeinsamem Linksklick lösen auch schnelle Angriffe die Strafe aus.", "El bloqueo repetido acorta o deja de renovar la ventana de bloqueo perfecto.\nLos ataques repetidos también lo causan si ataque y bloqueo comparten clic izquierdo.", "Defesas repetidas reduzem ou deixam de renovar a janela de defesa perfeita.\nAtaques repetidos também causam a penalidade se o clique esquerdo ataca e defende.", "Le difese ripetute riducono o smettono di rinnovare la finestra di difesa perfetta.\nAnche gli attacchi ripetuti attivano la penalità se il clic sinistro fa entrambe le cose.", "ป้องกันรัวทำให้ช่วงเวลาป้องกันสมบูรณ์สั้นลงหรือหยุดต่อเวลา\nโจมตีรัวก็กระตุ้นโทษนี้เมื่อคลิกซ้ายทั้งโจมตีและป้องกัน", "Đỡ liên tục làm ngắn hoặc ngừng làm mới cửa sổ đỡ hoàn hảo.\nĐánh liên tục cũng gây phạt khi chuột trái vừa đánh vừa đỡ.", "Defesas repetidas reduzem ou deixam de renovar a janela de defesa perfeita.\nAtaques repetidos também causam a penalização se o clique esquerdo ataca e defende.", "El bloqueo repetido acorta o deja de renovar la ventana de bloqueo perfecto.\nLos ataques repetidos también lo causan si ataque y bloqueo comparten clic izquierdo.");
            Editor("mod.partial", "键位或方案已保存，但玩法 Mod 操作失败；重试只处理未完成部分：{0}", "Bindings or scheme saved, but the gameplay mod failed. Retry handles only unfinished changes: {0}", "キーまたは設定は保存済みですが、Modの操作に失敗しました。未完了分のみ再試行します：{0}", "키 또는 설정은 저장되었으나 게임플레이 모드 작업에 실패했습니다. 재시도 시 미완료 부분만 처리합니다: {0}", "Клавиши или схема сохранены, но операция мода не удалась. Повтор затронет только незавершённое: {0}", "鍵位或方案已儲存，但玩法 Mod 操作失敗；重試只處理未完成部分：{0}", "Touches ou profil enregistrés, mais échec du mod de jeu. Réessayez uniquement les changements restants : {0}", "Tasten oder Profil gespeichert, Gameplay-Mod fehlgeschlagen. Erneuter Versuch bearbeitet nur offene Änderungen: {0}", "Teclas o perfil guardados, pero falló el mod de juego. Reintentar solo procesa lo pendiente: {0}", "Teclas ou perfil salvos, mas o mod de jogabilidade falhou. A nova tentativa trata apenas o que falta: {0}", "Tasti o profilo salvati, ma operazione mod non riuscita. Il nuovo tentativo gestisce solo le modifiche restanti: {0}", "บันทึกปุ่มหรือรูปแบบแล้ว แต่ม็อดการเล่นล้มเหลว ลองใหม่จะทำเฉพาะส่วนที่ยังไม่เสร็จ: {0}", "Đã lưu phím hoặc cấu hình nhưng thao tác mod lối chơi thất bại. Thử lại chỉ xử lý phần chưa xong: {0}", "Teclas ou perfil guardados, mas o mod de jogabilidade falhou. A nova tentativa trata apenas o que falta: {0}", "Teclas o perfil guardados, pero falló el mod de juego. Reintentar solo procesa lo pendiente: {0}");
            Editor("mod.title", "完美防御无连点惩罚", "Perfect guard: no rapid-click penalty", "ジャストガードの連打ペナルティなし", "완벽 방어 연타 페널티 제거", "Идеальный блок без штрафа частых нажатий", "完美防禦無連點懲罰", "Garde parfaite sans pénalité de répétition", "Perfekte Abwehr ohne Strafe für schnelle Klicks", "Bloqueo perfecto sin penalización por clics rápidos", "Defesa perfeita sem penalidade por cliques rápidos", "Difesa perfetta senza penalità per clic rapidi", "ป้องกันสมบูรณ์โดยไม่มีโทษกดรัว", "Đỡ hoàn hảo không phạt nhấp liên tục", "Defesa perfeita sem penalização por cliques rápidos", "Bloqueo perfecto sin penalización por clics rápidos");
            Editor("mod.note", "适用于所有键位方案和防御按键。启用或关闭前请退出游戏；取消勾选并应用即可恢复原规则。", "Applies to every binding scheme and guard key. Exit the game before enabling or disabling it; uncheck and apply to restore the original rules.", "すべてのキー設定と防御キーに適用されます。有効・無効を変更する前にゲームを終了してください。チェックを外して適用すると元のルールに戻ります。", "모든 키 설정과 방어 키에 적용됩니다. 켜거나 끄기 전에 게임을 종료하세요. 체크를 해제하고 적용하면 기존 규칙으로 돌아갑니다.", "Действует для всех схем и клавиш блока. Перед включением или отключением выйдите из игры; снимите флажок и примените изменения, чтобы вернуть исходные правила.", "適用於所有按鍵方案和防禦按鍵。啟用或關閉前請退出遊戲；取消勾選並套用即可恢復原規則。", "S’applique à tous les profils et touches de garde. Quittez le jeu avant d’activer ou de désactiver l’option ; décochez et appliquez pour rétablir les règles d’origine.", "Gilt für alle Tastenschemata und Abwehrtasten. Vor dem Ein- oder Ausschalten das Spiel beenden; zum Wiederherstellen der ursprünglichen Regeln abwählen und anwenden.", "Se aplica a todos los perfiles y teclas de bloqueo. Sal del juego antes de activarlo o desactivarlo; desmarca y aplica para restaurar las reglas originales.", "Vale para todos os perfis e teclas de defesa. Saia do jogo antes de ativar ou desativar; desmarque e aplique para restaurar as regras originais.", "Vale per tutti i profili e tasti di difesa. Esci dal gioco prima di attivarla o disattivarla; deseleziona e applica per ripristinare le regole originali.", "ใช้กับรูปแบบปุ่มและปุ่มป้องกันทั้งหมด ออกจากเกมก่อนเปิดหรือปิด ยกเลิกการเลือกแล้วกดใช้เพื่อคืนกฎเดิม", "Áp dụng cho mọi cấu hình phím và phím đỡ. Thoát trò chơi trước khi bật hoặc tắt; bỏ chọn rồi áp dụng để khôi phục quy tắc gốc.", "Aplica-se a todos os perfis e teclas de defesa. Saia do jogo antes de ativar ou desativar; desmarque e aplique para repor as regras originais.", "Se aplica a todos los perfiles y teclas de bloqueo. Sal del juego antes de activarlo o desactivarlo; desmarca y aplica para restaurar las reglas originales.");
            Editor("mod.enabled", "已启用", "Enabled", "有効", "활성화됨", "Включён", "已啟用", "Activé", "Aktiviert", "Activado", "Ativado", "Attivata", "เปิดใช้งานแล้ว", "Đã bật", "Ativado", "Activado");
            Editor("mod.disabled", "未启用", "Disabled", "無効", "비활성화됨", "Выключен", "未啟用", "Désactivé", "Deaktiviert", "Desactivado", "Desativado", "Disattivata", "ยังไม่เปิดใช้งาน", "Đã tắt", "Desativado", "Desactivado");
            Editor("mod.incomplete", "安装不完整", "Incomplete", "インストール未完了", "설치 미완료", "Установка неполная", "安裝不完整", "Incomplet", "Unvollständig", "Incompleto", "Incompleto", "Incompleta", "ติดตั้งไม่ครบ", "Chưa hoàn tất", "Incompleto", "Incompleto");
            Editor("mod.conflict", "Mod 目录中有其他或被改动的文件，请先移走这些文件再重试。", "The mod folder contains other or modified files. Move them out before retrying.", "Modフォルダーに別のファイルまたは変更されたファイルがあります。移動してから再試行してください。", "모드 폴더에 다른 파일이나 수정된 파일이 있습니다. 파일을 옮긴 후 다시 시도하세요.", "В папке мода есть посторонние или изменённые файлы. Переместите их и повторите.", "Mod 目錄中有其他或被變更的檔案，請先移走這些檔案再重試。", "Le dossier du mod contient des fichiers étrangers ou modifiés. Déplacez-les avant de réessayer.", "Der Mod-Ordner enthält fremde oder geänderte Dateien. Vor erneutem Versuch verschieben.", "La carpeta del mod contiene archivos ajenos o modificados. Muévelos antes de reintentar.", "A pasta do mod contém outros arquivos ou arquivos alterados. Mova-os antes de tentar novamente.", "La cartella della mod contiene file estranei o modificati. Spostali prima di riprovare.", "โฟลเดอร์ม็อดมีไฟล์อื่นหรือไฟล์ที่ถูกแก้ไข โปรดย้ายออกก่อนลองใหม่", "Thư mục mod chứa tệp khác hoặc tệp đã sửa. Hãy chuyển chúng ra trước khi thử lại.", "A pasta do mod contém outros ficheiros ou ficheiros alterados. Mova-os antes de tentar novamente.", "La carpeta del mod contiene archivos ajenos o modificados. Muévelos antes de reintentar.");
            Editor("mod.unsupported", "未找到所需游戏资源，请选择游戏根目录。", "Required game resource not found. Select the game's root folder.", "必要なゲームリソースがありません。ゲームのルートフォルダーを選択してください。", "필요한 게임 리소스를 찾지 못했습니다. 게임 루트 폴더를 선택하세요.", "Нужный ресурс игры не найден. Выберите корневую папку игры.", "未找到所需遊戲資源，請選擇遊戲根目錄。", "Ressource requise introuvable. Sélectionnez le dossier racine du jeu.", "Benötigte Spielressource fehlt. Wählen Sie den Stammordner des Spiels.", "No se encuentra el recurso necesario. Elige la carpeta raíz del juego.", "Recurso do jogo não encontrado. Selecione a pasta raiz do jogo.", "Risorsa richiesta non trovata. Seleziona la cartella principale del gioco.", "ไม่พบทรัพยากรเกมที่จำเป็น โปรดเลือกโฟลเดอร์หลักของเกม", "Không tìm thấy tài nguyên cần thiết. Hãy chọn thư mục gốc của trò chơi.", "Recurso do jogo não encontrado. Selecione a pasta raiz do jogo.", "No se encuentra el recurso necesario. Elige la carpeta raíz del juego.");
            Editor("mod.running", "请先退出游戏，再启用或关闭 Mod。", "Exit the game before enabling or disabling the mod.", "Modの有効・無効を変更する前にゲームを終了してください。", "모드를 켜거나 끄기 전에 게임을 종료하세요.", "Выйдите из игры, прежде чем включать или выключать мод.", "請先退出遊戲，再啟用或關閉 Mod。", "Quittez le jeu avant d'activer ou de désactiver le mod.", "Beenden Sie das Spiel, bevor Sie den Mod umschalten.", "Sal del juego antes de activar o desactivar el mod.", "Saia do jogo antes de ativar ou desativar o mod.", "Esci dal gioco prima di attivare o disattivare la mod.", "ออกจากเกมก่อนเปิดหรือปิดม็อด", "Thoát trò chơi trước khi bật hoặc tắt mod.", "Saia do jogo antes de ativar ou desativar o mod.", "Sal del juego antes de activar o desactivar el mod.");
            Editor("mod.verifyfailed", "Mod 文件写入验证失败，请重试。", "Mod file verification failed. Please retry.", "Modファイルの検証に失敗しました。再試行してください。", "모드 파일 확인에 실패했습니다. 다시 시도하세요.", "Проверка файлов мода не удалась. Повторите попытку.", "Mod 檔案寫入驗證失敗，請重試。", "Échec de la vérification des fichiers du mod. Réessayez.", "Mod-Dateiprüfung fehlgeschlagen. Bitte erneut versuchen.", "Falló la verificación del mod. Inténtalo de nuevo.", "Falha na verificação dos arquivos do mod. Tente novamente.", "Verifica dei file della mod non riuscita. Riprova.", "ตรวจสอบไฟล์ม็อดไม่สำเร็จ โปรดลองใหม่", "Xác minh tệp mod thất bại. Vui lòng thử lại.", "Falha na verificação dos ficheiros do mod. Tente novamente.", "Falló la verificación del mod. Inténtalo de nuevo.");
            Editor("mod.drafthint", "勾选仅暂存，点击“应用更改”后生效。", "Checking only stages the change. Click “Apply changes” to apply it.", "チェックは変更の仮保存です。「変更を適用」で反映されます。", "체크는 변경 사항을 임시로 저장합니다. “변경 적용”을 눌러야 반영됩니다.", "Флажок лишь подготавливает изменение. Нажмите «Применить изменения».", "勾選僅暫存，點擊「套用變更」後生效。", "Cocher prépare seulement la modification. Cliquez sur « Appliquer les modifications ».", "Die Auswahl merkt die Änderung nur vor. Erst „Änderungen anwenden“ setzt sie um.", "Marcar solo deja el cambio pendiente. Pulsa «Aplicar cambios» para aplicarlo.", "Marcar apenas prepara a alteração. Clique em “Aplicar alterações” para aplicá-la.", "La selezione prepara solo la modifica. Fai clic su «Applica modifiche» per applicarla.", "การเลือกเป็นเพียงการเตรียมการเปลี่ยนแปลง กด “ใช้การเปลี่ยนแปลง” เพื่อให้มีผล", "Đánh dấu chỉ lưu thay đổi chờ áp dụng. Nhấn “Áp dụng thay đổi” để thực hiện.", "Marcar apenas prepara a alteração. Clique em «Aplicar alterações» para a aplicar.", "Marcar solo deja el cambio pendiente. Pulsa «Aplicar cambios» para aplicarlo.");
        }
    }
